+import { evidenceLine, runSource } from './evidence';
+import { keyed } from './keyed';
+import { ADA, BEN, DB, MEMBER, OWNER, doc, match, mention, sql, words } from './ncReal';
+
+/**
+ * M2's alerts in the packaged desktop app (TXE-4673, NC-08h, for TXE-4500): for each Flow kind
+ * and both reply kinds, a real command makes Ben's row, the desktop signed in as Ben is handed
+ * exactly one alert for it, with that kind's text, and clicking it opens the row's entry route,
+ * which reveals the exact item, focused, and reads the row. A row Ben read before its alert was
+ * due is never alerted (NC-D09). Run only by okr/desktop/e2e/tab-readiness-native.sh in its NC
+ * profile (`run <run-dir> nc m2`), under a native UI lease, in a run-owned test package. macOS
+ * evidence only.
+ *
+ * What an alert is here: the shell's test notifier (OKR_DESKTOP_NOTIFY_LOG) records what the app
+ * handed to the OS and reports it shown; nothing reaches the person's screen. That is evidence of
+ * what the app asked the OS to show, never of a banner the OS displayed.
+ *
+ * The click's last step, from the entry route to the destination, needs a renderer that declares
+ * the flow and replies groups (contract.ts CLIENT_GROUPS, CC1's TXE-4672). On a build that
+ * declares okr only, those rows open as update_required and that step fails: this spec is the
+ * check that the switch closes the journey, and is run on a build that has it.
+ *
+ * Setup: all three source groups on, in this run's own database only; Ben's quiet hours off (the
+ * default 22:00-08:00 in the desktop's own zone would defer mentions and replies by the clock).
+ */
+test.describe.configure({ mode: 'serial' });
+
+const GROUPS = { 'X-OKR-Notification-Groups': 'okr,flow,replies' };
+type Json = Record<string, unknown>;
+
+const options = (): DesktopOptions => ({
+  app: process.env.OKR_TAB_APP ?? '',
+  tokenFile: process.env.OKR_TAB_TOKEN_FILE ?? '',
+  server: process.env.OKR_TAB_SERVER ?? '',
+  user: process.env.OKR_TAB_USER ?? '',
+  passwordFile: process.env.OKR_TAB_USER_PW_FILE ?? '',
+  runDir: process.env.OKR_TAB_RUN_DIR ?? '',
+});
+
+/** The run's dev-fixture okr-api, where setup writes as a principal. */
+async function dev(
+  request: APIRequestContext,
+  who: string,
+  method: string,
+  url: string,
+  data?: unknown,
+  headers: Record<string, string> = {},
+): Promise<Json> {
+  const answer = await request.fetch(`${process.env.OKR_NC_DEV_API}/api/v1${url}`, {
+    method,
+    data,
+    headers: {
+      'X-OKR-Dev-Principal': who,
+      'Idempotency-Key': randomUUID(),
+      ...keyed(method, url),
+      ...headers,
+    },
+  });
+  expect(answer.status(), `${method} ${url}: ${await answer.text()}`).toBeLessThan(300);
+  return answer.status() === 204 ? {} : ((await answer.json()) as Json);
+}
+
+const record = (what: string, fields: Record<string, string>) =>
+  console.log(
+    evidenceLine({
+      record: what,
+      database: DB,
+      source: runSource(),
+      at: new Date().toISOString(),
+      fields,
+    }),
+  );
+
+const day = (days: number) => new Date(Date.now() + days * 86_400_000).toISOString().slice(0, 10);
+const tag = () => randomUUID().slice(0, 6);
+
+/** Ben's one unwithdrawn row a subject caused, of `kind`, from this run's database. */
+function benRow(subject: string, kind: string): string {
+  const id = sql(
+    `SELECT id FROM ok_notifications WHERE subject_id = '${subject}' AND recipient_principal_id = '${BEN}' AND kind = '${kind}' AND withdrawn_at IS NULL ORDER BY arrival_seq DESC LIMIT 1`,
+  );
+  expect(id, `${kind} row for Ben on ${subject}`).toMatch(/^[0-9a-f-]{36}$/);
+  return id;
+}
+
+/** The alert candidate a row was recorded with: the id the desktop's alert carries. */
+const candidateOf = (row: string) =>
+  sql(`SELECT coalesce(candidate_id::text, '') FROM ok_notifications WHERE id = '${row}'`);
+
+/** The alerts the app handed to the (recording) OS notifier, in order. */
+function recorded(): { id: string; title: string; body: string }[] {
+  const file = process.env.OKR_DESKTOP_NOTIFY_LOG ?? '';
+  if (!existsSync(file)) return [];
+  return readFileSync(file, 'utf8')
+    .split('\n')
+    .filter(Boolean)
+    .map((l) => JSON.parse(l) as { id: string; title: string; body: string });
+}
+
+interface Expected {
+  kind: string;
+  row: string;
+  candidate: string;
+  text: string;
+  /** What the revealed item holds. */
+  shows: RegExp;
+}
+
